type persistentRefBuilder func() (newHash, expectedHash plumbing.Hash, err error)

func repositoryDirs(ctx context.Context, repo *git.Repository) (worktreeRoot, commonDir string, err error) {
	wt, err := repo.Worktree()
	if err != nil {
		return "", "", fmt.Errorf("open worktree: %w", err)
	}
	worktreeRoot = wt.Filesystem().Root()
	if worktreeRoot == "" {
		return "", "", errors.New("repository worktree filesystem has no root path")
	}
	commonDir, err = resolveGitCommonDir(ctx, repo)
	if err != nil {
		return "", "", err
	}
	return worktreeRoot, commonDir, nil
}

// casUpdateRef atomically updates refName through native Git's lock protocol.
// Pass ZeroHash as expectedHash to require that the ref does not exist.
func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
	newValue := newHash.String()
	oldValue := strings.Repeat("0", newHash.HexSize())
	if expectedHash != plumbing.ZeroHash {
		oldValue = expectedHash.String()
	}

	cmd := exec.CommandContext(ctx, "git", "update-ref", refName.String(), newValue, oldValue)
	cmd.Dir = repoRoot
	cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")
	output, err := cmd.CombinedOutput()
	if err == nil {
		return nil
	}

	out := string(output)
	if strings.Contains(out, "cannot lock ref") || strings.Contains(out, "but expected") {
		return ErrShadowRefBusy
	}
	return fmt.Errorf("git update-ref %s: %s: %w", refName, strings.TrimSpace(out), err)
}

func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create persistent ref lock directory: %w", err)
	}
	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
	return filepath.Join(lockDir, safe+".lock"), nil
}

func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
	path, err := persistentRefLockPath(commonDir, refName)
	if err != nil {
		return err
	}
	release, err := flock.AcquireContext(ctx, path)
	if err != nil {
		return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
	}
	defer release()
	return fn()
}

// updatePersistentRef serializes Entire writers for one ref and retains a CAS
// retry for native Git or other external writers. build runs again after every
// conflict, so each retry reconstructs its tree and commit from the fresh tip.
func updatePersistentRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, build persistentRefBuilder) error {
	repoRoot, commonDir, err := repositoryDirs(ctx, repo)
	if err != nil {
		return fmt.Errorf("resolve repository directories: %w", err)
	}

	return withPersistentRefFlock(ctx, commonDir, refName, func() error {
		for attempt := range shadowRefMaxRetries {
			newHash, expectedHash, buildErr := build()
			if buildErr != nil {
				return buildErr
			}

			refErr := casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
			if refErr == nil {
				return nil
			}
			if !errors.Is(refErr, ErrShadowRefBusy) {
				return fmt.Errorf("update persistent ref %s: %w", refName, refErr)
			}
			if newHash != expectedHash {
				tryDeleteLooseObject(commonDir, newHash)
			}

			if backoffErr := shadowRefBackoff(ctx, attempt); backoffErr != nil {
				return backoffErr
			}
		}

		logging.Warn(logging.WithComponent(ctx, "checkpoint"),
			"persistent ref CAS retry budget exhausted",
			slog.String("ref", refName.String()),
			slog.Int("retries", shadowRefMaxRetries),
		)
		return fmt.Errorf("failed to update persistent ref %s after %d CAS retries: %w", refName, shadowRefMaxRetries, ErrShadowRefBusy)
	})
}
package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"

	"github.com/go-git/go-git/v6/plumbing"
)

// ErrShadowRefBusy is returned by casUpdateShadowBranchRef when the ref has
// moved since the caller read it. Callers retry with a fresh parent.
var ErrShadowRefBusy = errors.New("shadow branch ref moved (CAS mismatch)")

// shadowRefMaxRetries bounds the WriteTemporary retry loop. With the
// per-shadow-branch flock held, our own writers never collide; this budget
// is purely a safety net against an external `git update-ref` writer that
// repeatedly beats us to the ref.
const shadowRefMaxRetries = 16

// shadowRefMaxJitter is the upper bound for randomized backoff between CAS
// retries. Random jitter avoids thundering-herd retry patterns when many
// sessions hit the same shadow branch simultaneously.
const shadowRefMaxJitter = 8 * time.Millisecond

// repoDirs returns the worktree root and git common dir for the store's
// repository. Callers use the worktree root as cmd.Dir for git invocations
// and the common dir to locate filesystem paths (lock files, loose objects)
// — both without depending on the process cwd.
func (s *ephemeralStore) repoDirs(ctx context.Context) (worktreeRoot, commonDir string, err error) {
	return repositoryDirs(ctx, s.repo)
}

// casUpdateShadowBranchRef atomically updates a shadow branch ref via
// `git update-ref <ref> <new> <old>`. Pass plumbing.ZeroHash as expectedHash
// to require the ref to NOT exist (first-checkpoint case).
//
// repoRoot is used as cmd.Dir so the update targets the same repository as
// the rest of WriteTemporary (i.e. s.repo) regardless of the process cwd.
//
// Returns ErrShadowRefBusy when git reports the ref moved since expectedHash
// was observed; callers retry with a fresh parent. Any other failure is
// returned wrapped.
//
// Why shell out: git's ref-locking is the canonical cross-process atomic
// CAS — go-git's CheckAndSetReference doesn't interoperate with native git's
// .lock files, and shadow branches can be touched concurrently by separate
// `entire` hook processes.
func casUpdateShadowBranchRef(ctx context.Context, repoRoot, branchName string, newHash, expectedHash plumbing.Hash) error {
	return casUpdateRef(ctx, repoRoot, plumbing.NewBranchReferenceName(branchName), newHash, expectedHash)
}

// shadowRefBackoff sleeps for a small random jitter before the next CAS
// retry. After several retries the upper bound doubles to slow the
// thundering herd further. Respects context cancellation.
func shadowRefBackoff(ctx context.Context, attempt int) error {
	base := shadowRefMaxJitter
	if attempt > 4 {
		base *= 2
	}
	// Add a 1ms floor so the chosen sleep is always non-trivial, even when
	// rand.Int64N happens to return 0.
	d := time.Duration(rand.Int64N(int64(base))) + time.Millisecond //nolint:gosec // jitter, not security-sensitive
	select {
	case <-time.After(d):
		return nil
	case <-ctx.Done():
		return ctx.Err() //nolint:wrapcheck // canonical context cancellation
	}
}

// shadowBranchLockPath returns the per-shadow-branch flock file path. Lock
// files live in <git-common-dir>/entire-shadow-locks/ so they don't pollute
// the session-state directory. Branch names are slash-escaped because the
// shadow-branch convention "entire/<hash>" would otherwise nest directories.
func shadowBranchLockPath(commonDir, branchName string) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-shadow-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create shadow lock directory: %w", err)
	}
	safe := strings.ReplaceAll(branchName, "/", "_")
	return filepath.Join(lockDir, safe+".lock"), nil
}

// withShadowBranchFlock acquires the per-shadow-branch flock, runs fn, and
// releases the flock. Serializes all WriteTemporary callers that target the
// same shadow branch — across goroutines AND across processes — so the CAS
// in casUpdateShadowBranchRef only sees external writers as contention.
//
// commonDir is the git common directory (from s.repoDirs); it locates the
// lock file independently of the process cwd.
func withShadowBranchFlock(commonDir, branchName string, fn func() error) error {
	path, err := shadowBranchLockPath(commonDir, branchName)
	if err != nil {
		return err
	}
	release, err := flock.Acquire(path)
	if err != nil {
		return fmt.Errorf("acquire shadow flock %s: %w", branchName, err)
	}
	defer release()
	return fn()
}

// tryDeleteLooseObject best-effort removes a loose object file. Used to
// clean up dangling commits created during a CAS-losing attempt. Failures
// (e.g. object already packed by a concurrent gc, or never written as a
// loose object) are ignored — the object will be picked up by the next gc
// pass either way.
func tryDeleteLooseObject(commonDir string, hash plumbing.Hash) {
	h := hash.String()
	if len(h) < 3 {
		return
	}
	_ = os.Remove(filepath.Join(commonDir, "objects", h[:2], h[2:]))
}
package strategy

import (
	"context"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"

	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// CleanupType identifies the type of item to clean up.
type CleanupType string

const (
	CleanupTypeShadowBranch CleanupType = "shadow-branch"
	CleanupTypeSessionState CleanupType = "session-state"
	CleanupTypeCheckpoint   CleanupType = "checkpoint"
	// CleanupTypeRedactCache is the redaction prefix cache in the git common dir.
	// Purely derived data -- it is rebuilt on the next checkpoint -- so it is
	// removed wholesale rather than per entry.
	CleanupTypeRedactCache CleanupType = "redact-cache"
)

// CleanupItem represents an item that can be cleaned up.
type CleanupItem struct {
	Type   CleanupType
	ID     string // Branch name, session ID, or checkpoint ID
	Reason string // Why this item is being cleaned
}

// CleanupResult contains the results of a cleanup operation.
type CleanupResult struct {
	RedactCaches      []string // Deleted redaction prefix cache directories
	ShadowBranches    []string // Deleted shadow branches
	SessionStates     []string // Deleted session state files
	Checkpoints       []string // Deleted checkpoint metadata
	FailedBranches    []string // Shadow branches that failed to delete
	FailedStates      []string // Session states that failed to delete
	FailedCheckpoints []string // Checkpoints that failed to delete
	FailedRedactCache []string // Redaction caches that failed to delete
}

// shadowBranchPattern matches shadow branch names in both old and new formats:
//   - Old format: entire/<commit[:7+]>
//   - New format: entire/<commit[:7+]>-<worktreeHash[:6]>
//
// The pattern requires at least 7 hex characters for the commit, optionally followed
// by a dash and exactly 6 hex characters for the worktree hash.
var shadowBranchPattern = regexp.MustCompile(`^entire/[0-9a-fA-F]{7,}(-[0-9a-fA-F]{6})?$`)

// IsShadowBranch returns true if the branch name matches the shadow branch pattern.
// Shadow branches have the format "entire/<commit-hash>-<worktree-hash>" where the
// commit hash is at least 7 hex characters and worktree hash is 6 hex characters.
// The "entire/checkpoints/v1" branch is NOT a shadow branch.
func IsShadowBranch(branchName string) bool {
	// Explicitly exclude metadata and trails branches
	if branchName == paths.MetadataBranchName || branchName == paths.TrailsBranchName {
		return false
	}
	return shadowBranchPattern.MatchString(branchName)
}

// ListShadowBranches returns all shadow branches in the repository.
// Shadow branches match the pattern "entire/<commit-hash>" (7+ hex chars).
// The "entire/checkpoints/v1" branch is excluded as it stores permanent metadata.
// Returns an empty slice (not nil) if no shadow branches exist.
func ListShadowBranches(ctx context.Context) ([]string, error) {
	heads, err := listShadowBranchHeads(ctx)
	if err != nil {
		return nil, err
	}
	branches := make([]string, 0, len(heads))
	for branch := range heads {
		branches = append(branches, branch)
	}
	sort.Strings(branches)
	return branches, nil
}

func listShadowBranchHeads(ctx context.Context) (map[string]plumbing.Hash, error) {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}
	defer repo.Close()

	refs, err := repo.References()
	if err != nil {
		return nil, fmt.Errorf("failed to get references: %w", err)
	}

	shadowBranches := map[string]plumbing.Hash{}

	err = refs.ForEach(func(ref *plumbing.Reference) error {
		if err := ctx.Err(); err != nil {
			return err //nolint:wrapcheck // Propagating context cancellation
		}
		// Only look at branch references
		if !ref.Name().IsBranch() {
			return nil
		}

		// Extract branch name without refs/heads/ prefix
		branchName := strings.TrimPrefix(ref.Name().String(), "refs/heads/")

		if IsShadowBranch(branchName) {
			shadowBranches[branchName] = ref.Hash()
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to iterate references: %w", err)
	}

	return shadowBranches, nil
}

// CleanupPushedShadowBranches deletes shadow branches whose sessions
// have fully condensed into committed checkpoint metadata (no active
// session referencing them, no pending turn-checkpoints awaiting
// finalization, and no ended-but-uncondensed session still relying on
// shadow-only data). Intended to be called only after a successful push
// so the caller knows any condensed checkpoint data already reached
// the remote.
//
// Returns the count of branches deleted. Failures (e.g., one branch
// fails to delete due to a stale lock) are logged but don't abort
// the operation — remaining branches are still attempted.
//
// Safety properties:
//   - Skips any shadow branch referenced by a session with EndedAt
//     == nil (still active).
//   - Skips any shadow branch whose session has TurnCheckpointIDs
//     pending (mid-finalize race window).
//   - Skips ended sessions until PhaseEnded and FullyCondensed prove the
//     shadow branch contents have been copied to committed metadata.
//   - Multiple sessions can share the same shadow branch (same base
//     commit + worktree); ALL must satisfy the criteria above.
//   - Shadow branches with no associated session state are deleted
//     (no session to lose data from).
func CleanupPushedShadowBranches(ctx context.Context) (int, error) {
	branchHeads, err := listShadowBranchHeads(ctx)
	if err != nil {
		return 0, fmt.Errorf("list shadow branches: %w", err)
	}
	if len(branchHeads) == 0 {
		return 0, nil
	}

	states, err := ListSessionStates(ctx)
	if err != nil {
		return 0, fmt.Errorf("list session states: %w", err)
	}

	// Build a set of shadow branch names that must be preserved
	// because at least one session still depends on them.
	protected := map[string]bool{}
	for _, s := range states {
		shadow, ok := protectedShadowBranchForSession(s)
		if ok {
			protected[shadow] = true
		}
	}

	toDelete := map[string]plumbing.Hash{}
	for b, hash := range branchHeads {
		if !protected[b] {
			toDelete[b] = hash
		}
	}
	if len(toDelete) == 0 {
		return 0, nil
	}

	deleted, failed := DeleteShadowBranchesIfUnchanged(ctx, toDelete)
	if len(failed) > 0 {
		logging.Warn(ctx, "some shadow branches failed to delete during post-push cleanup",
			slog.Int("failed_count", len(failed)),
			slog.Int("deleted_count", len(deleted)),
		)
	}
	return len(deleted), nil
}

// DeleteShadowBranchesIfUnchanged deletes shadow branches only if each branch
// still points at the hash observed by the caller. This avoids deleting a
// branch that another session advanced after cleanup's initial scan.
func DeleteShadowBranchesIfUnchanged(ctx context.Context, branches map[string]plumbing.Hash) (deleted []string, failed []string) {
	if len(branches) == 0 {
		return []string{}, []string{}
	}
	for branch, expected := range branches {
		if !IsShadowBranch(branch) || expected.IsZero() {
			failed = append(failed, branch)
			continue
		}
		protected, err := shadowBranchProtectedByCurrentState(ctx, branch)
		if err != nil {
			logging.Debug(ctx, "shadow branch unchanged-delete skipped after protection recheck failed",
				slog.String("branch", branch),
				slog.String("error", err.Error()),
			)
			failed = append(failed, branch)
			continue
		}
		if protected {
			logging.Debug(ctx, "shadow branch unchanged-delete skipped because current session state protects it",
				slog.String("branch", branch),
			)
			failed = append(failed, branch)
			continue
		}
		ref := "refs/heads/" + branch
		cmd := exec.CommandContext(ctx, "git", "update-ref", "-d", ref, expected.String())
		if output, runErr := cmd.CombinedOutput(); runErr != nil {
			logging.Debug(ctx, "shadow branch unchanged-delete skipped",
				slog.String("branch", branch),
				slog.String("expected", expected.String()),
				slog.String("output", strings.TrimSpace(string(output))),
				slog.String("error", runErr.Error()),
			)
			failed = append(failed, branch)
			continue
		}
		deleted = append(deleted, branch)
	}
	return deleted, failed
}

func protectedShadowBranchForSession(s *SessionState) (string, bool) {
	if s.Phase == session.PhaseEnded && s.FullyCondensed && len(s.TurnCheckpointIDs) == 0 {
		return "", false // safe — session ended cleanly and finalized
	}
	return getShadowBranchNameForCommit(s.BaseCommit, s.WorktreeID), true
}

func shadowBranchProtectedByCurrentState(ctx context.Context, branch string) (bool, error) {
	states, err := ListSessionStates(ctx)
	if err != nil {
		return false, err
	}
	for _, s := range states {
		shadow, ok := protectedShadowBranchForSession(s)
		if ok && shadow == branch {
			return true, nil
		}
	}
	return false, nil
}

// DeleteShadowBranches deletes the specified branches from the repository.
// Returns two slices: successfully deleted branches and branches that failed to delete.
// Individual branch deletion failures do not stop the operation - all branches are attempted.
func DeleteShadowBranches(ctx context.Context, branches []string) (deleted []string, failed []string, err error) { //nolint:unparam // already present in codebase
	if len(branches) == 0 {
		return []string{}, []string{}, nil
	}

	for _, branch := range branches {
		// Use git CLI to delete branches because go-git v5's RemoveReference
		// doesn't properly persist deletions with packed refs or worktrees
		if err := DeleteBranchCLI(ctx, branch); err != nil {
			failed = append(failed, branch)
			continue
		}

		deleted = append(deleted, branch)
	}

	return deleted, failed, nil
}

// DeleteOrphanedSessionStates deletes the specified session state files.
func DeleteOrphanedSessionStates(ctx context.Context, sessionIDs []string) (deleted []string, failed []string, err error) {
	if len(sessionIDs) == 0 {
		return []string{}, []string{}, nil
	}

	store, err := session.NewStateStore(ctx)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to create state store: %w", err)
	}

	for _, sessionID := range sessionIDs {
		if err := store.Clear(ctx, sessionID); err != nil {
			failed = append(failed, sessionID)
		} else {
			deleted = append(deleted, sessionID)
		}
	}

	return deleted, failed, nil
}

// DeleteOrphanedCheckpoints removes checkpoint directories from the entire/checkpoints/v1 branch.
