package strategy

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil"

	"github.com/stretchr/testify/require"
)

func TestRefLocks_ListedAndDeletedByCleanAll(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	lockFiles := []string{
		filepath.Join(tmpDir, ".git", "entire-persistent-ref-locks", "refs_entire_checkpoints_one.lock"),
		filepath.Join(tmpDir, ".git", "entire-shadow-locks", "entire_deadbeef.lock"),
	}
	for _, lockFile := range lockFiles {
		require.NoError(t, os.MkdirAll(filepath.Dir(lockFile), 0o750))
		require.NoError(t, os.WriteFile(lockFile, nil, 0o600))
	}

	items, err := ListAllItems(context.Background())
	require.NoError(t, err)
	require.Contains(t, cleanupItemTypes(items), CleanupType("ref-lock"))

	_, err = DeleteAllCleanupItems(context.Background(), items)
	require.NoError(t, err)
	for _, lockFile := range lockFiles {
		require.NoFileExists(t, lockFile)
	}
}

