 	return cleanupItems, nil
 }
+
+func listRefLockItems(ctx context.Context) ([]CleanupItem, error) {
+	commonDir, err := session.GetGitCommonDir(ctx)
+	if err != nil {
+		return nil, fmt.Errorf("resolve git common dir for ref locks: %w", err)
+	}
+
+	dirNames := []string{checkpoint.PersistentRefLockDirName, checkpoint.ShadowRefLockDirName}
+	var items []CleanupItem
+	for _, dirName := range dirNames {
+		entries, readErr := os.ReadDir(filepath.Join(commonDir, dirName))
