+		}
+		for _, entry := range entries {
+			if entry.Type() != 0 {
+				continue
+			}
+			items = append(items, CleanupItem{
+				Type:   CleanupTypeRefLock,
+				ID:     filepath.Join(dirName, entry.Name()),
+				Reason: "clean all",
+			})
+		}
+	}
+	return items, nil
+}
*** End Patch";
text(await tools.apply_patch(patch));

