	}

	cmd, stdout, stderr := newTestCleanCmd(t)
	err := runCleanAllWithItems(cmd.Context(), cmd, true, false, items, nil)

	if err == nil {
		t.Fatal("runCleanAllWithItems() should return error when items fail to delete")
